def is_nested(string):
    # A nested bracket in a valid subsequence exists iff the string contains
    # the subsequence "[[]]" (i.e., two '[' followed later by two ']').
    state = 0
    for ch in string:
        if state == 0 and ch == '[':
            state = 1
        elif state == 1 and ch == '[':
            state = 2
        elif state == 2 and ch == ']':
            state = 3
        elif state == 3 and ch == ']':
            return True
    return False
